// План specs/admin-access.md, 1.1 (кейс AA-01). Пользователь «בדיקה» (не admin). Только чтение. @prod-safe
import { test, expect } from '@playwright/test';
import { setLanguage } from '../admin-plans/plans-helpers';
import { DASHBOARD_URL, expectNoSupportConsole, waitForMenu } from './access-helpers';

test.use({ storageState: '../auth/user.json' });

test.describe('Support Console — доступ обычного пользователя (#09773471)', () => {
  test('Non-admin opening /supportinbox is redirected to the dashboard without Access Denied (EN) #09773471 @desktop @prod-safe', async ({ page }) => {
    await setLanguage(page, 'en');

    // Шаг 1: в меню нет служебных пунктов
    await page.goto('/dashboard');
    await waitForMenu(page);
    await expect(page.getByRole('link', { name: 'Support Console' })).toHaveCount(0);
    await expect(page.getByRole('link', { name: 'Admin Panel' })).toHaveCount(0);

    // Шаг 2: прямой заход → /dashboard
    await page.goto('/supportinbox');
    await expect(page).toHaveURL(DASHBOARD_URL);
    await expectNoSupportConsole(page);
    await expect(page.getByText('HISTORY', { exact: true })).toHaveCount(0);
  });
});
